//   Course Clips/ 1 - Bob-omb Battlefield/  Areas 1-3 & 1-5/1-5 Back GFX / layer 'Layer 2' / frame 1
void frame_3902_0(Activation& scope) {
    scope["count"] = 0;
    stop();
    _root["AreaTextClipF"]("Bob-Omb Battlefield:" + scope["newline"] + "<i>Secret of the Mountain</i>", 60);
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        _root["PauseGame"] = false;
        if (scope["count"] < 48) {
            _root["PauseGame"] = false;
            _root["Camspeed"] = 2;
            _root["Camcenter"] = scope["star"];
            _root["playpause"] = true;
            scope["count"]++;
        } else {
            if (scope["count"] < 150) {
                _root["PauseGame"] = false;
                scope["count"]++;
                _root["playpause"] = true;
                _root["MaxCamspeed"] = 35;
                _root["Camspeed"] = 30;
            } else {
                _root["playpause"] = false;
                nextFrame();
                _root["warpframe"] = false;
                scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
                    if (scope.self["warp1"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
                        _root["Course"]["Char"]["attack"] = true;
                        _root["Course"]["Char"]["xspeed"] = 0;
                        _root["Course"]["Char"]["yspeed"] = 0;
                        _root["Course"]["Char"]["attackFrame"] = "none";
                        scope["warp"] = true;
                        scope["warpnum"] = 1;
                    }
                    if (scope["warp"] == true && _root["warpframe"] == false) {
                        if (scope["warpnum"] == 1) {
                            _root["attachMovie"]("lefttransition", "lefttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
                        }
                        scope["warp"] = false;
                    }
                    if (_root["warpframe"] == true) {
                        if (scope["warpnum"] == 1) {
                            _root["changecourse"]("lefttransition2", "1-4", 1950, -650, 1950, -650, true);
                        }
                        //_root.warpframe = false;
                    }
                    return undefined;
                });
            }
        }
        return undefined;
    });
}

